package cryptoutil

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"fmt"
	"math/bits"
	"strconv"
	"strings"

	"golang.org/x/crypto/scrypt"
)

const (
	// saltLen is the length of the random salt generated by Hash.
	saltLen = 16
	// minSaltLen is the shortest salt Verify accepts from an encoded hash.
	minSaltLen = 8
	// maxEncodedKeyLen bounds the derived key length read from an encoded hash.
	maxEncodedKeyLen = 1024

	// Verify reads cost parameters from the stored hash, so it bounds them.
	// NewScryptHasher applies the same limits.
	maxScryptMemory = 1 << 28 // 128*N*r bytes: 256 MiB
	maxScryptR      = 32
	maxScryptP      = 16
	maxScryptWork   = 1 << 24 // N*r*p: 16x the default
)

// scryptCostTooHigh returns why (n, r, p) exceeds the limits above, or "".
// n and r must be positive.
func scryptCostTooHigh(n, r, p int) string {
	switch {
	case r > maxScryptR:
		return fmt.Sprintf("r must be <= %d", maxScryptR)
	case p > maxScryptP:
		return fmt.Sprintf("p must be <= %d", maxScryptP)
	case uint64(n) > maxScryptMemory/(128*uint64(r)):
		return fmt.Sprintf("memory cost 128*N*r must be <= %d MiB", maxScryptMemory>>20)
	case uint64(n)*uint64(r)*uint64(p) > maxScryptWork:
		return fmt.Sprintf("work N*r*p must be <= %d", maxScryptWork)
	}
	return ""
}

// b64 is the unpadded standard base64 used by the PHC string format.
var b64 = base64.RawStdEncoding

type scryptHasher struct {
	*scrypter
}

// NewScryptHasher creates a PasswordHasher that stores scrypt hashes as
// "$scrypt$ln=17,r=8,p=1$<salt>$<key>" (PHC string format; ln is log2(N)).
// Zero-valued fields of cfg are filled from DefaultScryptConfig. It applies the
// validation of NewScrypter and returns ErrInvalidParams if the cost exceeds the
// limits Verify enforces.
//
// For new password storage prefer NewArgon2idHasher.
func NewScryptHasher(cfg ScryptConfig) (PasswordHasher, error) {
	s, err := newScrypter(cfg)
	if err != nil {
		return nil, err
	}
	if reason := scryptCostTooHigh(s.n, s.r, s.p); reason != "" {
		return nil, fmt.Errorf("%w: scrypt %s", ErrInvalidParams, reason)
	}
	return &scryptHasher{scrypter: s}, nil
}

func (h *scryptHasher) Hash(password string) (string, error) {
	salt := make([]byte, saltLen)
	_, _ = rand.Read(salt) // never fails since Go 1.24
	key, err := h.DeriveKey([]byte(password), salt)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("$scrypt$ln=%d,r=%d,p=%d$%s$%s",
		bits.TrailingZeros(uint(h.n)), h.r, h.p, b64.EncodeToString(salt), b64.EncodeToString(key)), nil
}

func (h *scryptHasher) Verify(password, encoded string) error {
	p, err := parseScrypt(encoded)
	if err != nil {
		return err
	}
	key, err := scrypt.Key([]byte(password), p.salt, p.n, p.r, p.p, len(p.key))
	if err != nil {
		return fmt.Errorf("%w: %w", ErrKeyDerivation, err)
	}
	if subtle.ConstantTimeCompare(key, p.key) != 1 {
		return ErrMismatchedHash
	}
	return nil
}

func (h *scryptHasher) NeedsRehash(encoded string) bool {
	p, err := parseScrypt(encoded)
	if err != nil {
		return true
	}
	return p.n != h.n || p.r != h.r || p.p != h.p || len(p.key) != h.keyLen
}

type scryptEncoded struct {
	n, r, p   int
	salt, key []byte
}

// parseScrypt decodes and bounds-checks an encoded scrypt hash.
func parseScrypt(encoded string) (scryptEncoded, error) {
	var out scryptEncoded
	// "" "scrypt" "ln=..,r=..,p=.." salt key
	parts := strings.Split(encoded, "$")
	if len(parts) != 5 || parts[0] != "" || parts[1] != "scrypt" {
		return out, fmt.Errorf("%w: not an scrypt hash", ErrInvalidHash)
	}

	params, err := parseParams(parts[2], "ln", "r", "p")
	if err != nil {
		return out, err
	}
	ln, r, p := params[0], params[1], params[2]
	if ln < 1 || ln > 30 || r < 1 || p < 1 {
		return out, fmt.Errorf("%w: scrypt parameters out of range", ErrInvalidHash)
	}
	if reason := scryptCostTooHigh(1<<ln, r, p); reason != "" {
		return out, fmt.Errorf("%w: scrypt %s", ErrInvalidHash, reason)
	}
	out.n, out.r, out.p = 1<<ln, r, p

	if out.salt, out.key, err = parseSaltAndKey(parts[3], parts[4]); err != nil {
		return scryptEncoded{}, err
	}
	return out, nil
}

// parseParams parses "k1=v1,k2=v2,..." requiring exactly the given keys in order.
func parseParams(s string, keys ...string) ([]int, error) {
	fields := strings.Split(s, ",")
	if len(fields) != len(keys) {
		return nil, fmt.Errorf("%w: malformed parameters", ErrInvalidHash)
	}
	vals := make([]int, len(keys))
	for i, f := range fields {
		k, v, ok := strings.Cut(f, "=")
		if !ok || k != keys[i] {
			return nil, fmt.Errorf("%w: malformed parameters", ErrInvalidHash)
		}
		n, err := strconv.Atoi(v)
		if err != nil || n < 0 {
			return nil, fmt.Errorf("%w: malformed parameters", ErrInvalidHash)
		}
		vals[i] = n
	}
	return vals, nil
}

// parseSaltAndKey decodes the trailing salt and key fields of an encoded hash.
func parseSaltAndKey(saltField, keyField string) (salt, key []byte, err error) {
	salt, err = b64.DecodeString(saltField)
	if err != nil || len(salt) < minSaltLen {
		return nil, nil, fmt.Errorf("%w: bad salt", ErrInvalidHash)
	}
	key, err = b64.DecodeString(keyField)
	if err != nil || len(key) < minKeyLen || len(key) > maxEncodedKeyLen {
		return nil, nil, fmt.Errorf("%w: bad key", ErrInvalidHash)
	}
	return salt, key, nil
}
